const response = $input.first().json;
if (!response || response.status >= 400) {
  return [{ json: { error: response?.message || 'Error al generar el link del carrito', url: null, tiene_carrito_activo: false } }];
}
let url = response?.data?.url || response?.url || null;
if (!url) {
  return [{ json: { error: 'No se recibió URL en la respuesta', url: null, tiene_carrito_activo: false } }];
}
const carritoRow = $('Verificar Carrito Activo').first()?.json;
const tiene_carrito_activo = !!(carritoRow?.cart_id);
if (tiene_carrito_activo && !url.includes('mode=')) {
  url += '&mode=modify';
}
return [{ json: { url, tiene_carrito_activo } }];
